{{(() => {
     // What happens at the door for the chosen "Кой плаща", priced by the server with the
     // same code as the real order (PortalQuote) - laid out like the console's box (2026-10-02).
     const en = appsmith.store.bo_lang === 'en';
     const payer = NewPaymentMethodSelect.selectedOptionValue || 'all';
     const eur = (v) => Number(v || 0).toLocaleString('bg-BG', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
     if (!OrderShippingSelect.selectedOptionValue) {
       return en ? 'Choose the delivery type to see the fees' : 'Изберете вид доставка, за да видите таксите';
     }
     if (payer !== 'nothing' && !(Number(String(NewAmountInput.text || '').replace(',', '.')) > 0)) {
       return en ? 'Enter the COD amount to see what is collected' : 'Въведете наложения платеж, за да видите сумата за събиране';
     }
     if (PortalQuote.isLoading) return '…';
     const q = PortalQuote.data || {};
     if (q.delivery === undefined) return '';
     const fees = (en ? 'delivery ' : 'доставка ') + eur(q.delivery) + ' · ' + (en ? 'COD fee ' : 'такса НП ') + eur(q.cod_fee);
     if (payer === 'all') {
       return (en ? 'Total to collect: ' : 'Сума за събиране: ') + eur(q.collected) + '\n'
         + (en ? 'COD amount (goods) ' : 'Стока (наложен платеж) ') + eur(q.goods) + ' · ' + fees + '\n'
         + (en ? 'You receive ' : 'Вие получавате ') + eur(q.owed_to_merchant);
     }
     if (payer === 'fees') {
       return (en ? 'Total to collect: ' : 'Сума за събиране: ') + eur(q.collected) + '\n'
         + (en ? 'Our fees only: ' : 'Само нашите такси: ') + fees + '\n'
         + (en ? 'The goods were paid to you already.' : 'Стоката е платена на вас предварително.');
     }
     // No наложен платеж: no COD amount and no percentage fee - the delivery alone (2026-10-02).
     return (en ? 'The driver collects nothing.' : 'Шофьорът не събира нищо.') + '\n'
       + (en ? 'On your weekly invoice: delivery ' : 'Във вашата седмична фактура: доставка ') + eur(q.invoiced);
   })()}}
